# field helper

def n(id, label, default, unit='', **kw):
    x={'id':id,'label':label,'type':'number','default':default}
    if unit: x['unit']=unit
    x.update(kw); return x

def d(id,label,default='TODAY'):
    return {'id':id,'label':label,'type':'date','default':default}

def t(id,label,default=''):
    return {'id':id,'label':label,'type':'text','default':default}

def s(id,label,default,options):
    return {'id':id,'label':label,'type':'select','default':default,'options':[{'value':a,'label':b} for a,b in options]}

specs=[]
def add(slug,title,cat,typ,phrase,desc,fields,example,formula,faqs):
    specs.append({'slug':slug,'title':title,'category':cat,'type':typ,'primaryKeyword':phrase,'description':desc,'fields':fields,'example':example,'formula':formula,'faqs':faqs})

